#include "services/RecommendationService.h"
#include "utils/Utils.h"
#include <algorithm>
RecommendationService::RecommendationService(Repository&r,StudentService&s,ClubService&c):repository_(r),students_(s),clubs_(c){rebuild();}
// Shared, normalized interest nodes connect students to clubs for graph traversal.
void RecommendationService::rebuild(){graph_.clear();const auto students=students_.all();const auto clubs=clubs_.all();for(const auto&s:students){const auto studentNode="student:"+s.id;graph_.addVertex(studentNode);for(const auto&interest:s.interests)graph_.addEdge(studentNode,"interest:"+toLowerCopy(interest));}for(const auto&c:clubs){const auto clubNode="club:"+c.id;graph_.addVertex(clubNode);for(const auto&interest:c.interests)graph_.addEdge(clubNode,"interest:"+toLowerCopy(interest));for(const auto&member:c.memberIds)graph_.addEdge(clubNode,"student:"+member);}}
// Exclude current memberships after traversing; shared interest paths may reach clubs the student already joined.
std::vector<Club> RecommendationService::recommendClubs(const std::string&studentId,std::size_t maximum)const{students_.get(studentId);std::vector<Club> result;std::unordered_map<std::string,bool> alreadyMember;for(const auto&c:clubs_.all())for(const auto&m:c.memberIds)if(m==studentId)alreadyMember[c.id]=true;const auto reached=graph_.breadthFirstSearch("student:"+studentId,1000);std::unordered_map<std::string,bool> reachable;for(const auto&node:reached)reachable[node]=true;for(const auto&c:clubs_.all()){if(!alreadyMember[c.id]&&reachable["club:"+c.id])result.push_back(c);}std::sort(result.begin(),result.end(),[](const Club&a,const Club&b){return a.name<b.name;});if(result.size()>maximum)result.resize(maximum);return result;}
std::vector<Event> RecommendationService::recommendEvents(const std::string&studentId,std::size_t maximum)const{const auto clubs=recommendClubs(studentId,maximum);std::unordered_map<std::string,bool> clubIds;for(const auto&c:clubs)clubIds[c.id]=true;std::vector<Event> result;for(const auto&e:repository_.allEvents())if(clubIds[e.clubId])result.push_back(e);std::sort(result.begin(),result.end(),[](const Event&a,const Event&b){return a.date+a.time<b.date+b.time;});if(result.size()>maximum)result.resize(maximum);return result;}
